def task_lock(self, task_id: str) -> threading.Lock:
    """按任务的锁：result.json、草稿版本号的读-改-写都在这把锁里（P1-3、P2-2）。"""
    with self._guard:
        return self._task_locks.setdefault(task_id, threading.Lock())

